// composer-draft: saves the prompt box to composer-draft.json on every change,
// so TBD can park a session with a draft in the box, and fills a saved draft
// back into the box when the session resumes in a new process.
import type {
  EngineInterface,
  Frozen,
  PromptBox,
  PromptChangeOrigin,
  RenderElement,
  RenderInput,
} from 'claude-code'

import { describe, resolveContext, writeJSON } from '../shared/session.ts'
import type { SessionContext } from '../shared/session.ts'

export const FEATURE = 'composer-draft'
export const RESTORE_RETRY_MS = 500
export const NOTICE_MS = 3_000

/** The plugin's own name, as a `plugin` origin names the plugin that filled. */
const PLUGIN = 'tbd'

/** Between two drafts in composer-draft.unrestored. */
const UNRESTORED_SEPARATOR = '\n\n--- unrestored draft ---\n\n'

const restoredIncarnation = { plugin: 'tbd', key: 'composerDraftRestoredIncarnation' } as const
const notice = { plugin: 'tbd', key: 'composerDraftNotice' } as const
const restorableMark = { plugin: 'tbd', key: 'composerDraftRestorable' } as const

type AbovePromptEvent = Frozen<RenderInput<'AbovePrompt'>>

/**
 * A box to save, and what it does to the restorable mark: whether the box's
 * text holds all of the draft. `restorable` sets the mark; left out, the box
 * keeps the mark as the boxes before it left it.
 */
export type QueuedBox = { box: PromptBox; restorable?: boolean }

export type DraftWriter = {
  queue(box: PromptBox, restorable?: boolean): void
  flush(): Promise<void>
}

/**
 * Writes boxes one at a time. A box queued while a write runs replaces any box
 * queued behind it, so an older box never lands after a newer one; a box that
 * keeps the mark takes over the mark the box it replaces set, so dropping that
 * box never drops its mark. An empty box sets the mark restorable. A write
 * that rejects is dropped and the next box is still written; `write` logs its
 * own failures.
 */
export function createDraftWriter(write: (queued: QueuedBox) => Promise<void>): DraftWriter {
  let queued: QueuedBox | undefined
  let running: Promise<void> | undefined

  async function drain(): Promise<void> {
    while (queued !== undefined) {
      const next = queued
      queued = undefined
      try {
        await write(next)
      } catch {
        // Dropped: `write` reports its own failures.
      }
    }
    running = undefined
  }

  return {
    queue(box, restorable) {
      const mark = box.text === '' ? true : (restorable ?? queued?.restorable)
      queued = mark === undefined ? { box } : { box, restorable: mark }
      running ??= drain()
    },
    async flush() {
      while (running !== undefined) {
        await running
      }
    },
  }
}

/**
 * The composer-draft.json record of a box: its text, cursor and whether the
 * text holds all of the draft, or no draft. The daemon reads the numbers as
 * integers, so they are written whole.
 */
export function draftRecord(sessionId: string, box: PromptBox, restorable: boolean, now: number): object {
  const savedAtMs = Math.trunc(now)
  if (box.text === '') {
    return { schemaVersion: 1, sessionId, hasDraft: false, savedAtMs }
  }
  return {
    schemaVersion: 1,
    sessionId,
    hasDraft: true,
    text: box.text,
    cursor: Math.trunc(box.cursor),
    restorable,
    savedAtMs,
  }
}

let writer: DraftWriter | undefined

/**
 * The restorable mark this load holds; undefined until the first box that
 * keeps it reads it from `$.state`, where it outlives a reload. Only the
 * writer, which runs one box at a time, reads or sets it.
 */
let restorable: boolean | undefined

/** True from the start of a restore until it lands, settles otherwise, or fails. */
let restoring = false

/**
 * The draft the pending restore is filling, until the change its fill raised
 * arrives: that change carries the draft's mark.
 */
let ownFill: SavedText | undefined

function draftWriter($: EngineInterface): DraftWriter {
  writer ??= createDraftWriter(queued => saveBox($, queued))
  return writer
}

async function saveBox($: EngineInterface, queued: QueuedBox): Promise<void> {
  try {
    const ctx = await resolveContext($)
    if (ctx !== null) {
      const mark = await settleMark($, queued.restorable)
      await writeJSON($, `${ctx.dir}/composer-draft.json`, draftRecord(ctx.sessionId, queued.box, mark, await $.clock.now()))
    }
  } catch (error) {
    log($, `could not save the draft: ${describe(error)}`)
  }
}

/** Applies a box's change to the mark, and answers the mark the box is saved with. */
async function settleMark($: EngineInterface, change: boolean | undefined): Promise<boolean> {
  if (change === undefined) {
    restorable ??= await readMark($)
    return restorable
  }
  if (change !== restorable) {
    restorable = change
    try {
      await $.state.set(restorableMark, change)
    } catch (error) {
      log($, `could not keep the restorable mark: ${describe(error)}`)
    }
  }
  return change
}

/**
 * The mark an earlier load kept. Never set means nothing marked the box. A
 * read that fails could hide a mark, so it reads as not restorable.
 */
async function readMark($: EngineInterface): Promise<boolean> {
  try {
    return (await $.state.get(restorableMark)).value ?? true
  } catch (error) {
    log($, `could not read the restorable mark: ${describe(error)}`)
    return false
  }
}

/** A saved draft: its text, and whether that text holds all of it. */
type SavedText = { text: string; restorable: boolean }

/** What composer-draft.json holds at a session's start. */
type SavedDraft =
  /** No file, or a file recording an empty box. */
  | { kind: 'none' }
  | ({ kind: 'draft' } & SavedText)
  /** A file that is there but cannot be read: it may hold a draft, so it is kept. */
  | { kind: 'unreadable'; reason: string }

async function readSavedDraft($: EngineInterface, ctx: SessionContext): Promise<SavedDraft> {
  const path = `${ctx.dir}/composer-draft.json`
  if (!(await $.fs.exists(path))) {
    return { kind: 'none' }
  }
  let file: string
  try {
    file = await $.fs.read(path)
  } catch (error) {
    return { kind: 'unreadable', reason: describe(error) }
  }
  let record: unknown
  try {
    record = JSON.parse(file)
  } catch {
    return { kind: 'unreadable', reason: 'not JSON' }
  }
  const fields =
    typeof record === 'object' && record !== null
      ? (record as { hasDraft?: unknown; text?: unknown; restorable?: unknown })
      : {}
  if (typeof fields.hasDraft !== 'boolean') {
    return { kind: 'unreadable', reason: 'no hasDraft' }
  }
  if (!fields.hasDraft) {
    return { kind: 'none' }
  }
  if (typeof fields.text !== 'string' || fields.text === '') {
    return { kind: 'unreadable', reason: 'a draft without text' }
  }
  return { kind: 'draft', text: fields.text, restorable: fields.restorable === true }
}

/**
 * Fills the saved draft into the empty box, retrying every RESTORE_RETRY_MS
 * while the box refuses it (not mounted yet, or under a dialog). When the
 * person's own text reaches the box first, the box is left alone and the
 * draft is added to composer-draft.unrestored. Each outcome is recorded in
 * composer-draft.restore.json. Resolves after one attempt and never rejects;
 * the retries run on timers.
 */
export async function restoreDraft($: EngineInterface, ctx: SessionContext, draft: SavedText): Promise<void> {
  try {
    const box = await $.prompt.read()
    if (box.text !== '') {
      await keepUnrestored($, ctx, draft.text)
      await $.state.set(restoredIncarnation, ctx.incarnationId)
      restoring = false
      await recordRestore($, ctx, 'unrestored')
      return
    }
    ownFill = draft
    const filled = await $.prompt.fill({ text: draft.text, mode: 'replace' })
    if (!filled.isFilled) {
      // Still pending: the retry runs on a timer.
      ownFill = undefined
      $.clock.after(RESTORE_RETRY_MS, () => void restoreDraft($, ctx, draft))
      return
    }
    await $.state.set(restoredIncarnation, ctx.incarnationId)
    restoring = false
    await $.state.set(notice, draft.restorable ? 'restored' : 'restoredWithoutPaste')
    $.clock.after(NOTICE_MS, () => void hideNotice($))
    log($, 'restored')
    await recordRestore($, ctx, 'restored')
  } catch (error) {
    restoring = false
    log($, `restore failed: ${describe(error)}`)
  }
}

/**
 * Adds a draft to composer-draft.unrestored: as the whole text when there is
 * no file, else after the drafts already there and UNRESTORED_SEPARATOR, so a
 * later rescue never replaces an earlier one. A file that is there but cannot
 * be read is left alone, since writing it would drop the drafts it holds.
 */
async function keepUnrestored($: EngineInterface, ctx: SessionContext, text: string): Promise<void> {
  const path = `${ctx.dir}/composer-draft.unrestored`
  let kept: string | undefined
  if (await $.fs.exists(path)) {
    try {
      kept = await $.fs.read(path)
    } catch (error) {
      log($, `could not read composer-draft.unrestored, left it alone and dropped the draft: ${describe(error)}`)
      return
    }
  }
  await $.fs.write(path, kept === undefined ? text : `${kept}${UNRESTORED_SEPARATOR}${text}`)
  log($, 'box was not empty, saved the draft to composer-draft.unrestored')
}

/**
 * Overwrites composer-draft.restore.json with a restore's outcome, so the soak
 * can count restores from the session directories without Claude's debug log.
 */
async function recordRestore($: EngineInterface, ctx: SessionContext, outcome: 'restored' | 'unrestored'): Promise<void> {
  try {
    await writeJSON($, `${ctx.dir}/composer-draft.restore.json`, {
      schemaVersion: 1,
      sessionId: ctx.sessionId,
      incarnationId: ctx.incarnationId,
      outcome,
      atMs: Math.trunc(await $.clock.now()),
    })
  } catch (error) {
    log($, `could not record the restore: ${describe(error)}`)
  }
}

async function hideNotice($: EngineInterface): Promise<void> {
  try {
    await $.state.set(notice, 'hidden')
  } catch (error) {
    log($, `could not hide the notice: ${describe(error)}`)
  }
}

function log($: EngineInterface, text: string): void {
  $.ui.log(`${FEATURE}: ${text}`, { to: 'debug' })
}

// The feature's hooks, which register.ts calls for a spawn that listed
// composer-draft. Each catches its own failures: a feature never fails a hook.

/** Restores the saved draft, once per process. */
export async function sessionStart($: EngineInterface, ctx: SessionContext): Promise<void> {
  try {
    // A notice still up was raised by an earlier load, whose timer went with it.
    const shown = (await $.state.get(notice)).value
    if (shown !== undefined && shown !== 'hidden') {
      await $.state.set(notice, 'hidden')
    }
    // A reload fires session.start again in the same process; the draft is
    // already in the box there.
    if ((await $.state.get(restoredIncarnation)).value === ctx.incarnationId) {
      return
    }
    const saved = await readSavedDraft($, ctx)
    if (saved.kind === 'unreadable') {
      // It may hold a draft: neither overwrite it nor settle this process.
      log($, `could not read composer-draft.json, left it alone: ${saved.reason}`)
      return
    }
    if (saved.kind === 'none') {
      // Nothing to restore: save the box as it stands so the file exists, and
      // settle this process, so a later reload never takes the person's own
      // draft for one to restore.
      draftWriter($).queue(await $.prompt.read())
      await $.state.set(restoredIncarnation, ctx.incarnationId)
      return
    }
    restoring = true
    void restoreDraft($, ctx, { text: saved.text, restorable: saved.restorable })
  } catch (error) {
    log($, `session.start failed: ${describe(error)}`)
  }
}

/**
 * Saves the box one last time and waits for every queued write. An empty box
 * is not queued: the edit or clear that emptied it was saved already, and a
 * box the shutdown has unmounted reads empty too, which must not overwrite
 * the draft a park relies on.
 */
export async function sessionEnd($: EngineInterface, ctx: SessionContext): Promise<void> {
  try {
    const box = await $.prompt.read()
    const draft = draftWriter($)
    if (box.text !== '') {
      draft.queue(box)
    }
    await draft.flush()
  } catch (error) {
    log($, `session.end failed for ${ctx.sessionId}: ${describe(error)}`)
  }
}

/**
 * The box after one of the person's edits; queued, never awaited. An edit
 * keeps the mark: typing after a paste does not put the paste in the text. An
 * empty box is not saved while a restore is pending, because it would
 * overwrite the saved draft before the fill lands.
 */
export function promptEdited($: EngineInterface, box: PromptBox): void {
  if (restoring && box.text === '') {
    return
  }
  draftWriter($).queue(box)
}

/**
 * The box after any other change: a clear, a recalled entry, a fill. Such a
 * change can put content in the box that its text does not hold (a collapsed
 * paste, an image), so any origin but a clear or a plugin's fill marks a box
 * it leaves non-empty as not restorable. The feature's own restore fill
 * carries the saved draft's mark, and loses it when the engine changed the
 * text it filled (an over-long text collapsed). An empty box is not saved
 * while a restore is pending.
 */
export function promptChanged($: EngineInterface, box: PromptBox, origin: Frozen<PromptChangeOrigin>): void {
  if (restoring && box.text === '') {
    return
  }
  draftWriter($).queue(box, markAfterChange(box, origin))
}

function markAfterChange(box: PromptBox, origin: Frozen<PromptChangeOrigin>): boolean | undefined {
  switch (origin.kind) {
    case 'clear':
      return true
    case 'plugin': {
      if (origin.name !== PLUGIN || ownFill === undefined) {
        return undefined
      }
      const fill = ownFill
      ownFill = undefined
      return fill.restorable && box.text === fill.text
    }
    default:
      return box.text === ''
  }
}

/**
 * Draws the restore notice above what is drawn beneath, while it is visible.
 * A draft marked not restorable came back as its text alone, without the
 * pasted content (a collapsed paste, an image) its placeholders stand for,
 * and the notice says so.
 */
export async function abovePrompt(
  $: EngineInterface,
  e: AbovePromptEvent,
  below: () => Promise<RenderElement>,
): Promise<RenderElement> {
  const shown = await $.state.get(notice).then(
    read => read.value ?? 'hidden',
    () => 'hidden',
  )
  if (shown === 'hidden') {
    return below()
  }
  const { Box, Text } = $.ui.resolve(e)
  return (
    <Box flexDirection="column">
      <Text dimColor>
        {shown === 'restored' ? 'Restored your unsent draft' : 'Restored your unsent draft, but not its pasted content'}
      </Text>
      {await below()}
    </Box>
  )
}

"""#),
        (path: "hooks/features/prompt-answer.ts", body: #"""
// prompt-answer: lets TBD answer this session's permission dialogs and
// AskUserQuestion from cards in the transcript pane, while the terminal stays
// able to answer each (docs/specs/2026-10-20-mod-channel-prompt-answer-design.md,
// "Answering prompts").
//
// - tool.call records every call in flight, so a permission dialog, whose
//   payload carries no tool call id, can be paired with its call by input.
// - classic.PermissionRequest opens the dialog's card and waits on its own
//   held request for TBD's answer. Holding a `$` call keeps the hook's own
//   ten-second clock stopped; a plain promise would not.
// - AskUserQuestion is answered from tool.call, which races the dialog
//   (`next(e)`) against TBD's answer.
//
// Whoever answers second loses: Claude Code takes the first answer, and the
// mod tells the daemon which it was (a receipt for TBD's, `closed` for the
// terminal's). Every way out of a hook withdraws its dialog's entry, except a
// permission hook that ran short of budget: its entry stands until the call
// ends, and tool.call then sends `closed`. Receipts are awaited, so none is
// dropped when the hook returns. `closed` goes out from the channel's outbox
// (queueReport), a timer of the module's own: a terminal No or Escape aborts
// the hook, and with it every `$` call the hook makes afterwards.
import type {
  ClassicEventOf,
  ClassicResultOf,
  EngineInterface,
  Frozen,
  Next,
  NextBudget,
  PermissionRequestDecision,
  ToolCallInput,
  ToolCallResult,
} from 'claude-code'

import {
  POLL_BACKOFF_MS,
  isRecord,
  isReportStanding,
  queueReport,
  request,
  standReport,
  standingReportBody,
  withdrawReport,
} from '../shared/channel.ts'
import type { ChannelEnv } from '../shared/channel.ts'

export const FEATURE = 'prompt-answer'

/** Consecutive failed answer waits a permission dialog survives (a daemon restart) before it is left to the terminal. */
export const ANSWER_RETRY_LIMIT = 5
/** The pause between a permission dialog's failed answer waits. It is the hook's own time, so the retries stay inside its budget. */
export const ANSWER_RETRY_MS = 1_000
/** The least hook budget a permission retry pause may start with; below it the dialog is left to the terminal. */
export const ANSWER_BUDGET_FLOOR_MS = 2_000
/**
 * The pauses after a question's first, second, third and every later failed
 * answer wait in a row: the poll's backoff. A question waits from tool.call
 * while its dialog is pending, when the hook's clock is stopped, so it retries
 * until the dialog settles.
 */
export const QUESTION_RETRY_MS: readonly number[] = POLL_BACKOFF_MS

const OPEN_PATH = '/v1/prompts/open'
const QUESTION_TOOL = 'AskUserQuestion'

// The keys tool.call's input carries beside the tool's own arguments.
const RESERVED_KEYS = new Set(['tool', 'tool_use_id', 'agentId', 'requestMeta', 'consent'])

type PermissionRequestInput = ClassicEventOf['classic.PermissionRequest']
type PermissionRequestResult = ClassicResultOf['classic.PermissionRequest']

type ToolCallNext = Next<'tool.call'>
type PermissionRequestNext = Next<'classic.PermissionRequest'>

/** A tool call whose `next(e)` has not settled. */
type CallInFlight = {
  toolUseId: string
  /** The call's arguments, keys sorted, as JSON: what a permission payload's tool_input is compared by. */
  args: string
  agentId: string | undefined
  /** Set once a permission dialog has claimed the call. */
  isPaired: boolean
  /**
   * Set once the permission hook returned TBD's deny. Whether it took effect
   * shows only when the tool's `next(e)` settles: a terminal Yes before it
   * does not abort the hook, and Claude Code then ignores the deny.
   */
  isDenyReturned: boolean
}

/** Calls in flight by tool use id, oldest first (a Map keeps insertion order). */
const callsInFlight = new Map<string, CallInFlight>()

/**
 * How a dialog's answer wait treats failures: a permission hook spends its own
 * budget on retries and gives up; a question, waiting while its dialog's
 * `next(e)` is pending, retries until the dialog settles.
 */
type RetryRule = 'budgeted' | 'untilSettled'

/** What a wait for TBD's answer ended with. */
type AnswerOutcome =
  | { kind: 'decision'; decision: Record<string, unknown> }
  | { kind: 'resolved' }
  | { kind: 'aborted' }
  | { kind: 'failed' }
  | { kind: 'outOfBudget' }

// MARK: - tool.call

/**
 * tool.call: records the call while `next(e)` runs. AskUserQuestion is also
 * answered here; any other call whose dialog is still open when the tool
 * finishes was answered Yes in the terminal, and the mod says so.
 */
export async function toolCalled(
  $: EngineInterface,
  env: ChannelEnv,
  e: Frozen<ToolCallInput>,
  next: ToolCallNext,
): Promise<ToolCallResult> {
  const toolUseId: unknown = e.tool_use_id
  if (typeof toolUseId !== 'string' || toolUseId === '') {
    return next(e)
  }
  const args = argsOf(e)
  callsInFlight.set(toolUseId, {
    toolUseId,
    args: stableJSON(args),
    agentId: typeof e.agentId === 'string' ? e.agentId : undefined,
    isPaired: false,
    isDenyReturned: false,
  })
  let result: ToolCallResult | undefined
  try {
    if (String(e.tool) === QUESTION_TOOL) {
      result = await answerQuestion($, env, e, next, toolUseId, args)
    } else {
      result = await next(e)
    }
    return result
  } finally {
    const isDenyReturned = callsInFlight.get(toolUseId)?.isDenyReturned === true
    callsInFlight.delete(toolUseId)
    if (isDenyReturned) {
      // TBD's deny took effect when the call ended denied or errored; a call
      // that ran means the terminal's Yes came first. A call that threw says
      // neither, and the daemon reports the answer unconfirmed.
      if (result !== undefined) {
        const wasDenied = 'deny' in result || result.isError === true
        if (wasDenied) {
          await postReport($, env, toolUseId)
        } else {
          queueClosed($, env, toolUseId)
        }
      }
    } else if (withdrawReport(toolUseId)) {
      // The terminal answered: a question Escaped there aborts this hook too.
      queueClosed($, env, toolUseId)
    }
  }
}

async function answerQuestion(
  $: EngineInterface,
  env: ChannelEnv,
  e: Frozen<ToolCallInput>,
  next: ToolCallNext,
  toolUseId: string,
  args: Record<string, unknown>,
): Promise<ToolCallResult> {
  // Opens the dialog in the terminal. While it is pending the hook's clock is
  // stopped, so racing it against a plain promise is safe.
  const dialog = next(e)
  let isDialogSettled = false
  const dialogSettled = dialog.then(
    result => {
      isDialogSettled = true
      return { kind: 'terminal' as const, result }
    },
    error => {
      isDialogSettled = true
      throw error
    },
  )
  // A dialog TBD answered settles after the hook has returned; nothing reads it.
  dialogSettled.catch(() => {})

  // The dialog is open from here on. Whatever goes wrong on TBD's side, the
  // hook returns the dialog's own result: a throw would reach register.ts's
  // catch, which calls next(e) again and opens a second dialog.
  try {
    return await raceDialog($, env, toolUseId, args, next, dialog, dialogSettled, () => isDialogSettled)
  } catch (error) {
    $.ui.log(`prompt-answer: question ${toolUseId} fell back to the terminal: ${String(error)}`, { to: 'debug' })
    return dialog
  }
}

/** answerQuestion past `next(e)`: opens the card and races TBD's answer against the dialog. */
async function raceDialog(
  $: EngineInterface,
  env: ChannelEnv,
  toolUseId: string,
  args: Record<string, unknown>,
  next: ToolCallNext,
  dialog: Promise<ToolCallResult>,
  dialogSettled: Promise<{ kind: 'terminal'; result: ToolCallResult }>,
  isDialogSettled: () => boolean,
): Promise<ToolCallResult> {
  const isOpen = await openDialog($, env, {
    toolUseID: toolUseId,
    sessionID: await $.session.id(),
    toolName: QUESTION_TOOL,
    toolInput: args,
    suggestions: null,
  })
  if (!isOpen) {
    return dialog
  }

  const answered = awaitAnswer($, env, toolUseId, next.signal, next.budget, 'untilSettled', isDialogSettled).then(
    outcome => ({ kind: 'tbd' as const, outcome }),
  )
  const first = await Promise.race([dialogSettled, answered])
  if (first.kind === 'terminal') {
    // The finally in toolCalled sends `closed`.
    return first.result
  }

  const outcome = first.outcome
  if (outcome.kind === 'decision') {
    const updatedInput = outcome.decision.updatedInput
    if (
      outcome.decision.behavior === 'allow' &&
      isRecord(updatedInput) &&
      updatedInput.questions !== undefined &&
      isRecord(updatedInput.answers) &&
      !next.signal.aborted &&
      !isDialogSettled()
    ) {
      withdrawReport(toolUseId)
      await postReport($, env, toolUseId)
      return { result: { questions: updatedInput.questions, answers: updatedInput.answers } } as ToolCallResult
    }
    $.ui.log(`prompt-answer: question ${toolUseId} got no usable answer`, { to: 'debug' })
  }
  if (outcome.kind === 'failed') {
    // No wait stands behind the card any more, so a reconnect must not post
    // it again.
    withdrawReport(toolUseId)
  }
  // TBD's side ended without an answer: the terminal keeps the dialog, and the
  // finally sends `closed` once it settles while the card still stands.
  return dialog
}

// MARK: - classic.PermissionRequest

/**
 * classic.PermissionRequest: pairs the dialog with its call, opens its card,
 * and waits for TBD's answer while the dialog stays usable in the terminal.
 * Never sets `interrupt`.
 */
export async function permissionRequested(
  $: EngineInterface,
  env: ChannelEnv,
  e: Frozen<PermissionRequestInput>,
  next: PermissionRequestNext,
): Promise<PermissionRequestResult> {
  if (e.tool_name === QUESTION_TOOL) {
    return next(e)
  }
  const call = pairCall(e.tool_input, typeof e.agent_id === 'string' ? e.agent_id : undefined)
  if (call === null) {
    return next(e)
  }
  const toolUseId = call.toolUseId
  const isOpen = await openDialog($, env, {
    toolUseID: toolUseId,
    sessionID: await $.session.id(),
    toolName: e.tool_name,
    toolInput: e.tool_input ?? null,
    suggestions: e.permission_suggestions ?? null,
  })
  if (!isOpen) {
    return next(e)
  }

  const outcome = await awaitAnswer($, env, toolUseId, next.signal, next.budget, 'budgeted', () => !isReportStanding(toolUseId))
  if (outcome.kind === 'decision' && !next.signal.aborted && withdrawReport(toolUseId)) {
    const decision = permissionDecision(outcome.decision)
    if (decision !== null) {
      if (decision.behavior === 'deny') {
        // Confirmed by toolCalled once the call ends: a terminal Yes may have
        // come first, and then the tool runs whatever the card said.
        call.isDenyReturned = true
      } else {
        // An allow and a terminal Yes end alike (the tool runs), so the
        // receipt goes at once.
        await postReport($, env, toolUseId)
      }
      return { decision }
    }
    $.ui.log(`prompt-answer: dialog ${toolUseId} got an unusable decision`, { to: 'debug' })
    queueClosed($, env, toolUseId)
    return next(e)
  }
  // The hook's budget ran low: the dialog stays the terminal's, and its card
  // stays standing so toolCalled sends `closed` once the call ends.
  if (outcome.kind === 'outOfBudget') {
    return next(e)
  }
  // The terminal answered (No or Escape abort the hook), the daemon resolved
  // the prompt, or it could not be reached: the dialog stays the terminal's.
  // After an abort this hook's own `$` calls fail, so the close goes out from
  // the outbox's timer.
  if (withdrawReport(toolUseId) && outcome.kind !== 'resolved') {
    queueClosed($, env, toolUseId)
  }
  return next(e)
}

/**
 * The oldest unpaired call in flight with exactly these arguments in the same
 * agent, claimed; null when none matches. Calls with identical arguments are
 * interchangeable, so the oldest is as good as any.
 */
function pairCall(toolInput: unknown, agentId: string | undefined): CallInFlight | null {
  const args = stableJSON(toolInput)
  for (const call of callsInFlight.values()) {
    if (!call.isPaired && call.args === args && call.agentId === agentId) {
      call.isPaired = true
      return call
    }
  }
  return null
}

/** A decision as Claude Code takes it, or null for a shape it would refuse. Drops `interrupt`. */
function permissionDecision(raw: Record<string, unknown>): PermissionRequestDecision | null {
  if (raw.behavior === 'allow') {
    const decision: Record<string, unknown> = { behavior: 'allow' }
    if (isRecord(raw.updatedInput)) {
      decision.updatedInput = raw.updatedInput
    }
    if (Array.isArray(raw.updatedPermissions)) {
      decision.updatedPermissions = raw.updatedPermissions
    }
    return decision as PermissionRequestDecision
  }
  if (raw.behavior === 'deny') {
    const decision: Record<string, unknown> = { behavior: 'deny' }
    if (typeof raw.message === 'string') {
      decision.message = raw.message
    }
    return decision as PermissionRequestDecision
  }
  return null
}

// MARK: - The dialog's requests

/**
 * Posts `open` and, when the daemon takes it, keeps it standing so the poll
 * loop posts it again after a reconnect. False when the daemon refused it
 * (the feature is off) or could not be reached.
 */
async function openDialog($: EngineInterface, env: ChannelEnv, body: { toolUseID: string } & Record<string, unknown>): Promise<boolean> {
  const reply = await request($, env, 'POST', OPEN_PATH, body)
  if (reply === null || reply.status !== 200) {
    $.ui.log(`prompt-answer: ${body.toolUseID} was not opened (${reply?.status ?? 'no reply'})`, { to: 'debug' })
    return false
  }
  // Standing, the poll loop posts it again after a reconnect
  // (repostStandingReports in channel.ts).
  standReport(body.toolUseID, OPEN_PATH, body)
  return true
}

/**
 * Waits on held answer requests, one after another, until TBD answers, the
 * daemon resolves the prompt, `signal` aborts, or `isOver` says the dialog
 * ended. A failed wait (a daemon restart) is retried, posting the dialog open
 * again first:
 * - `budgeted` (a permission hook, whose pauses spend its own budget): after
 *   ANSWER_RETRY_MS, until ANSWER_RETRY_LIMIT in a row, or until the budget
 *   would not outlast the pause (ANSWER_BUDGET_FLOOR_MS);
 * - `untilSettled` (a question, waiting while its dialog's `next(e)` holds the
 *   hook's clock): after QUESTION_RETRY_MS, for as long as the dialog is open,
 *   so a card that outlives a daemon restart can still be answered.
 */
async function awaitAnswer(
  $: EngineInterface,
  env: ChannelEnv,
  toolUseId: string,
  signal: AbortSignal,
  budget: NextBudget,
  rule: RetryRule,
  isOver: () => boolean,
): Promise<AnswerOutcome> {
  const path = `/v1/prompts/${encodeURIComponent(toolUseId)}/answer`
  let failures = 0
  // A failure in a row; false once a budgeted wait has failed too often.
  const recordFailure = (): boolean => {
    failures += 1
    return rule === 'untilSettled' || failures < ANSWER_RETRY_LIMIT
  }
  for (;;) {
    if (signal.aborted) {
      return { kind: 'aborted' }
    }
    if (isOver()) {
      return { kind: 'resolved' }
    }
    if (failures > 0) {
      // A permission hook's pause is its own time; past its budget the hook is skipped.
      if (rule === 'budgeted' && budget.remainingMs < ANSWER_BUDGET_FLOOR_MS) {
        return { kind: 'outOfBudget' }
      }
      const pause = rule === 'budgeted' ? ANSWER_RETRY_MS : questionRetryDelay(failures)
      try {
        await $.clock.sleep(pause, { signal })
      } catch {
        return { kind: 'aborted' }
      }
      if (isOver()) {
        return { kind: 'resolved' }
      }
      // A restarted daemon has forgotten the prompt: open it again first.
      const body = standingReportBody(toolUseId)
      if (body !== undefined && (await request($, env, 'POST', OPEN_PATH, body)) === null) {
        if (!recordFailure()) {
          return { kind: 'failed' }
        }
        continue
      }
    }
    const reply = await untilAborted(request($, env, 'GET', path), signal)
    if (signal.aborted) {
      return { kind: 'aborted' }
    }
    const json = reply?.status === 200 && isRecord(reply.json) ? reply.json : null
    if (json?.state === 'decision' && isRecord(json.decision)) {
      return { kind: 'decision', decision: json.decision }
    }
    if (json?.state === 'resolved') {
      return { kind: 'resolved' }
    }
    if (json?.state === 'pending') {
      failures = 0
      continue
    }
    $.ui.log(`prompt-answer: answer wait for ${toolUseId} failed (${reply?.status ?? 'no reply'})`, { to: 'debug' })
    if (!recordFailure()) {
      return { kind: 'failed' }
    }
  }
}

/** A question's pause after `failures` failed waits in a row. */
function questionRetryDelay(failures: number): number {
  return QUESTION_RETRY_MS[Math.min(failures - 1, QUESTION_RETRY_MS.length - 1)] ?? 10_000
}

/** Resolves `work`, or null as soon as `signal` aborts. */
function untilAborted<T>(work: Promise<T>, signal: AbortSignal): Promise<T | null> {
  if (signal.aborted) {
    return Promise.resolve(null)
  }
  return new Promise<T | null>(resolve => {
    const onAbort = (): void => resolve(null)
    signal.addEventListener('abort', onAbort, { once: true })
    work.then(
      value => {
        signal.removeEventListener('abort', onAbort)
        resolve(value)
      },
      () => {
        signal.removeEventListener('abort', onAbort)
        resolve(null)
      },
    )
  })
}

/**
 * Posts `receipt` for a dialog TBD answered and waits for the daemon's reply,
 * so the post is not dropped when the hook returns. One local round trip; a
 * `$` call in flight stops the hook's clock. It runs only on paths the
 * terminal has not aborted. A failure is logged at debug by `request` and
 * otherwise ignored: never rejects.
 */
async function postReport($: EngineInterface, env: ChannelEnv, toolUseId: string): Promise<void> {
  await request($, env, 'POST', `/v1/prompts/${encodeURIComponent(toolUseId)}/receipt`, {})
}

/**
 * Tells the daemon the terminal answered a dialog. Sent from the channel's
 * outbox, not awaited: the hook may already be aborted, and its own `$` calls
 * with it.
 */
function queueClosed($: EngineInterface, env: ChannelEnv, toolUseId: string): void {
  queueReport($, env, `/v1/prompts/${encodeURIComponent(toolUseId)}/closed`, { by: 'terminal' })
}

// MARK: - Pairing keys

/** tool.call's input less the keys that are not the tool's arguments. */
function argsOf(e: Frozen<ToolCallInput>): Record<string, unknown> {
  const args: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(e)) {
    if (!RESERVED_KEYS.has(key)) {
      args[key] = value
    }
  }
  return args
}

/** JSON with every object's keys sorted, so equal values compare equal as text. */
export function stableJSON(value: unknown): string {
  return JSON.stringify(sortKeys(value)) ?? 'undefined'
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(sortKeys)
  }
  if (isRecord(value)) {
    const sorted: Record<string, unknown> = {}
    for (const key of Object.keys(value).sort()) {
      sorted[key] = sortKeys(value[key])
    }
    return sorted
  }
  return value
}

